-- 읽기 전용 운영 DB 구조 지문 조회(데이터 행 미조회). 격리 시험 DB의 기반 스키마·구조 일치 검증용(대표 2026-11-26 지시).
-- 보안(이 저장소는 공개라 실행 기록도 공개 — 민감 가능 정보는 출력하지 않는다): 함수 본문·정책식·검사식·색인식·트리거 문장은 글자를 내보내지 않고 md5 지문만 낸다
-- (본문은 이미 저장소 migration에 있으므로 다시 추출하지 않고, 격리 DB의 같은 조회 결과와 지문으로 대조). 컬럼 기본값도 글자를 내보내지 않고 md5 지문만 낸다(낱말 필터 없음).
-- 비교 한계: 기본값은 지문만 있어 기반 스키마의 기본값 글자를 이 결과로 복원할 수 없다(기반 열의 기본값은 migration·앱 코드로 따로 확정).
-- 설정값은 PostgREST 노출 스키마(pgrst.db_schemas)만 읽고 그 밖의 역할 설정(비밀 가능)은 읽지 않는다. 함수 설정(proconfig 배열)은 search_path 항목 하나만 꺼내고 다른 항목은 읽지 않는다.
-- 함수는 오버로드(인자 모드·타입)별로 한 줄이며 실행 권한(anon·authenticated·service_role·public)도 그 줄에 붙인다.
\pset tuples_only on
\pset format unaligned
select jsonb_build_object('kind','env','extensions',(select jsonb_agg(extname order by extname) from pg_catalog.pg_extension),'schemas',(select jsonb_agg(nspname order by nspname) from pg_catalog.pg_namespace where nspname not like 'pg_%' and nspname <> 'information_schema'),'publications',(select jsonb_agg(jsonb_build_object('pub',pubname,'tables',(select jsonb_agg(schemaname||'.'||tablename order by tablename) from pg_catalog.pg_publication_tables t where t.pubname=p.pubname)) order by pubname) from pg_catalog.pg_publication p),'postgrest_schemas',(select jsonb_agg(substring(c from 'pgrst.db_schemas=(.*)')) from pg_catalog.pg_db_role_setting s join pg_catalog.pg_roles r on r.oid=s.setrole cross join lateral unnest(s.setconfig) c where r.rolname='authenticator' and c like 'pgrst.db_schemas=%'),'roles',(select jsonb_agg(jsonb_build_object('role',rolname,'bypassrls',rolbypassrls,'super',rolsuper,'login',rolcanlogin) order by rolname) from pg_catalog.pg_roles where rolname in ('anon','authenticated','service_role','authenticator')))::text;
select jsonb_build_object('kind','tables','rows',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','storage') and c.relkind in ('r','p','v','m')))::text;
select jsonb_build_object('kind','columns','rows',(select jsonb_agg(jsonb_build_object('t',table_name,'c',column_name,'n',ordinal_position,'udt',udt_name,'len',character_maximum_length,'null',is_nullable,'def_md5',case when column_default is null then null else md5(column_default) end,'ident',is_identity,'gen',generation_expression is not null) order by table_name,ordinal_position) from information_schema.columns where table_schema='public'))::text;
select jsonb_build_object('kind','constraints','rows',(select jsonb_agg(jsonb_build_object('t',tc.table_name,'name',tc.constraint_name,'type',tc.constraint_type,'cols',(select jsonb_agg(k.column_name order by k.ordinal_position) from information_schema.key_column_usage k where k.constraint_schema=tc.constraint_schema and k.constraint_name=tc.constraint_name and k.table_name=tc.table_name),'check',(select md5(cc.check_clause) from information_schema.check_constraints cc where cc.constraint_schema=tc.constraint_schema and cc.constraint_name=tc.constraint_name),'ref',(select jsonb_build_object('table',u.table_name,'del',r.delete_rule,'upd',r.update_rule) from information_schema.referential_constraints r join information_schema.table_constraints u on u.constraint_schema=r.unique_constraint_schema and u.constraint_name=r.unique_constraint_name where r.constraint_schema=tc.constraint_schema and r.constraint_name=tc.constraint_name limit 1)) order by tc.table_name,tc.constraint_name) from information_schema.table_constraints tc where tc.table_schema='public' and tc.constraint_type in ('PRIMARY KEY','UNIQUE','FOREIGN KEY','CHECK') and tc.constraint_name not like '%_not_null'))::text;
select jsonb_build_object('kind','indexes','rows',(select jsonb_agg(jsonb_build_object('t',tablename,'name',indexname,'md5',md5(indexdef)) order by tablename,indexname) from pg_catalog.pg_indexes where schemaname='public'))::text;
select jsonb_build_object('kind','views','rows',(select jsonb_agg(jsonb_build_object('name',table_name,'md5',md5(view_definition)) order by table_name) from information_schema.views where table_schema='public'))::text;
select jsonb_build_object('kind','routines','rows',(select jsonb_agg(jsonb_build_object('schema',r.routine_schema,'name',r.routine_name,'type',r.routine_type,'returns',r.data_type,'lang',r.external_language,'security',r.security_type,'body_md5',md5(coalesce(r.routine_definition,'')),'search_path',(select c from pg_catalog.pg_proc a cross join lateral unnest(a.proconfig) c where a.oid=(reverse(split_part(reverse(r.specific_name),'_',1)))::oid and c like 'search_path=%' limit 1),'exec',(select jsonb_agg(g.grantee order by g.grantee) from information_schema.routine_privileges g where g.specific_schema=r.specific_schema and g.specific_name=r.specific_name and g.privilege_type='EXECUTE' and g.grantee in ('anon','authenticated','service_role','public')),'params',(select jsonb_agg(jsonb_build_object('n',p.parameter_name,'udt',p.udt_name,'mode',p.parameter_mode,'has_default',p.parameter_default is not null) order by p.ordinal_position) from information_schema.parameters p where p.specific_schema=r.specific_schema and p.specific_name=r.specific_name)) order by r.routine_schema,r.routine_name,r.specific_name) from information_schema.routines r where r.routine_schema not in ('pg_catalog','information_schema','extensions','auth','storage','graphql','graphql_public','realtime','vault','net','cron','pgsodium','pgsodium_masks','supabase_functions','supabase_migrations','pgbouncer')))::text;
select jsonb_build_object('kind','triggers','rows',(select jsonb_agg(jsonb_build_object('schema',event_object_schema,'t',event_object_table,'name',trigger_name,'event',event_manipulation,'timing',action_timing,'orient',action_orientation,'md5',md5(coalesce(action_statement,'')||coalesce(action_condition,''))) order by event_object_schema,event_object_table,trigger_name,event_manipulation) from information_schema.triggers where event_object_schema in ('public','auth','storage')))::text;
select jsonb_build_object('kind','policies','rows',(select jsonb_agg(jsonb_build_object('schema',schemaname,'t',tablename,'name',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'using_md5',md5(coalesce(qual,'')),'check_md5',md5(coalesce(with_check,''))) order by schemaname,tablename,policyname) from pg_catalog.pg_policies where schemaname in ('public','storage')))::text;
select jsonb_build_object('kind','grants','tables',(select jsonb_agg(jsonb_build_object('t',table_name,'g',grantee,'p',privilege_type) order by table_name,grantee,privilege_type) from information_schema.table_privileges where table_schema='public' and grantee in ('anon','authenticated','service_role','public')),'columns',(select jsonb_agg(jsonb_build_object('t',table_name,'c',column_name,'g',grantee,'p',privilege_type) order by table_name,column_name,grantee,privilege_type) from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated','service_role','public')))::text;
select jsonb_build_object('kind','sequences_types','sequences',(select jsonb_agg(jsonb_build_object('name',sequence_name,'type',data_type) order by sequence_name) from information_schema.sequences where sequence_schema='public'),'enums',(select jsonb_agg(jsonb_build_object('type',t.typname,'labels',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_catalog.pg_enum e where e.enumtypid=t.oid)) order by t.typname) from pg_catalog.pg_type t join pg_catalog.pg_namespace n on n.oid=t.typnamespace where t.typtype='e' and n.nspname='public'))::text;
